type Screen='chat'|'companies'|'briefing'|'videos'|'ask'|'saved'|'sources';
type FeedLocation={screen:Exclude<Screen,'ask'>;company:string;topic:string;period:string;query:string;more:number;scroll:number};
function readFeedLocation():FeedLocation{
 const fallback:FeedLocation={screen:'chat',company:'',topic:'',period:'all',query:'',more:8,scroll:0};
 try{const value=JSON.parse(localStorage.getItem('newsroom-feed-location')||'null');if(!value||!['chat','companies','briefing','videos','saved','sources'].includes(value.screen))return fallback;return {...fallback,...value,more:Math.max(8,Math.min(250,Number(value.more)||8)),scroll:Math.max(0,Number(value.scroll)||0)}}catch{return fallback}
}
type AudioTrack={url:string;title:string;voice:string};
type AudioItem=AudioTrack&{tracks?:AudioTrack[]};
const TOPICS=['AI research','Product launches','Robotics','Business','Earnings','Regulation'];
const NAV=[{id:'chat' as Screen,label:'Article feed',icon:MessageCircle},{id:'briefing' as Screen,label:'Daily briefing',icon:Sun},{id:'companies' as Screen,label:'Company news',icon:Globe},{id:'videos' as Screen,label:'Watch & learn',icon:VideoIcon},{id:'ask' as Screen,label:'Chats',icon:Sparkles}];
const screenLabels:Record<Screen,string>={chat:'Article feed',companies:'Company news',briefing:'Daily briefing',videos:'Watch & learn',ask:'Chats',saved:'Saved articles',sources:'Source directory'};
const dateText=(value:string|null,timezone='Europe/London')=>value?new Date(value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:value.length===10?'UTC':timezone}):'Publication date unavailable';
const timeText=(value:string|null,timezone='Europe/London')=>value&&value.length>10?new Date(value).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:timezone}):'—';
function CompanyLogo({ceo}:{ceo:CEO}){return <span className="company-logo" role="img" aria-label={ceo.company} style={{backgroundColor:ceo.color,maskImage:`url(/logos/${ceo.company.toLowerCase()}.svg)`,WebkitMaskImage:`url(/logos/${ceo.company.toLowerCase()}.svg)`,maskSize:'contain',maskPosition:'center',maskRepeat:'no-repeat'}}/>}
function SourceCitation({article,timezone}:{article:Article;timezone:string}){return <a className="source-citation" href={article.url} target="_blank" rel="noopener noreferrer"><span className="source-mark"><Globe size={12}/></span>{article.source}<ArrowUpRight size={12}/><span className="citation-date">{dateText(article.published_at,timezone)}</span></a>}

function AudioPlayer({item,onClose,speed}:{item:AudioItem;onClose:()=>void;speed:number}){
 const ref=useRef<HTMLAudioElement>(null);const advance=useRef(false);const [playing,setPlaying]=useState(false);const [rate,setRate]=useState(speed);const [error,setError]=useState('');const [index,setIndex]=useState(0);const tracks=item.tracks||[item];const current=tracks[index];
 useEffect(()=>{const a=ref.current;if(a)a.playbackRate=rate},[rate,index]);
 useEffect(()=>{if(advance.current){advance.current=false;ref.current?.play().catch(()=>setError('Press play to continue narration'))}},[index]);
 return <motion.div className="audio-player" initial={{y:70,opacity:0}} animate={{y:0,opacity:1}}><span className="audio-icon"><Headphones size={20}/></span><div><strong>{current.title}</strong><small>AI-generated · {current.voice}{tracks.length>1?` · ${index+1}/${tracks.length}`:''}</small>{error&&<small>{error}</small>}</div><audio ref={ref} src={current.url} onPlay={()=>setPlaying(true)} onPause={()=>setPlaying(false)} onEnded={()=>{setPlaying(false);if(index+1<tracks.length){advance.current=true;setIndex(index+1)}}} onError={()=>setError('Audio could not be played')}/><button className="round-button" aria-label={playing?'Pause narration':'Play narration'} onClick={()=>{if(playing)ref.current?.pause();else ref.current?.play().catch(()=>setError('Press play again to start audio'))}}>{playing?<Pause size={18}/>:<Play size={18}/>}</button><button className="icon-button" aria-label="Stop narration" onClick={()=>{if(ref.current){ref.current.pause();ref.current.currentTime=0}advance.current=false;setIndex(0)}}><Square size={15}/></button><select aria-label="Playback speed" value={rate} onChange={e=>setRate(Number(e.target.value))}><option value={.75}>0.75×</option><option value={1}>1×</option><option value={1.25}>1.25×</option><option value={1.5}>1.5×</option><option value={2}>2×</option></select><button className="icon-button" aria-label="Close audio player" onClick={onClose}><X size={17}/></button></motion.div>
}

function NewsCard({article,ceos,prefs,onSave,onAudio,onReply,index,savingArticle}:{article:Article;ceos:CEO[];prefs:Preferences;onSave:(id:string)=>void;onAudio:(text:string,presenter:string,title:string)=>void;onReply:(article:Article)=>void;index:number;savingArticle:string|null}){
 const [expanded,setExpanded]=useState(false);const [imageFailed,setImageFailed]=useState(false);const ceo=ceos.find(c=>c.id===article.presenters[0]);const saved=prefs.saved.includes(article.id);
 return <motion.article className="news-message" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:Math.min(index*.04,.2)}} style={{'--company':ceo?.color||'#b3b9b0'} as CSSProperties}>
  <CEOAvatar ceo={ceo}/><div className="message-content"><div className="message-byline"><strong>{ceo?.name||'The Newsroom'}</strong>{ceo&&<span className="presenter-company">{ceo.company}</span>}<span className="ai-label">AI presenter</span><time>{timeText(article.published_at,prefs.timezone)}</time></div><p className="intro">{article.summary_kind==='AI summary'?'Here’s what’s happening.':'From the latest reporting.'}{article.companies.length>1&&<span className="cross-company"> With {article.companies.filter(c=>c!==ceo?.company).join(' & ')}</span>}</p>
  <div className={`news-card ${index===0?'featured':''}`}><div className="article-topline"><span className="topic-dot"/>{article.topics[0]}<span className="article-kind">{article.summary_kind}</span></div><div className="article-body"><div><h3><a href={article.url} target="_blank" rel="noopener noreferrer">{article.title}</a></h3><p className={expanded?'':'clamp-summary'}>{article.summary}</p></div>{article.image&&!imageFailed&&<img className="article-image" src={article.image} alt="" loading="lazy" referrerPolicy="no-referrer" onError={()=>setImageFailed(true)}/>}</div>
  {expanded&&<div className="expanded-story">{article.why_it_matters&&<p><strong>Why it matters</strong>{article.why_it_matters}</p>}<small>Grounded in {article.source} metadata and excerpts. Read the original for the full report.</small>{article.companies.length>1&&<div className="co-presenters">{article.presenters.map(id=><CEOAvatar key={id} ceo={ceos.find(c=>c.id===id)} size={28}/>)}<span>A shared story</span></div>}</div>}
  <SourceCitation article={article} timezone={prefs.timezone}/><div className="article-actions"><button onClick={()=>setExpanded(!expanded)}>{expanded?'Less detail':'Read the briefing'}<ChevronDown size={13} className={expanded?'rotated':''}/></button><div><button className="ask-article-button" aria-label={`Ask about ${article.title}`} onClick={()=>onReply(article)}><MessageCircle size={15}/>Ask this article</button><button className="icon-button" aria-label={`Listen to ${article.title}`} onClick={()=>onAudio(article.summary,ceo?.id||'sam_altman',article.title)}><Volume2 size={16}/></button><button className={`article-like ${saved?'is-liked':''}`} aria-label={saved?'Unlike article and remove from Saved articles':'Like article and save to Saved articles'} aria-pressed={saved} aria-busy={savingArticle===article.id} disabled={savingArticle!==null} title={saved?'Remove from Saved articles':'Like and save this article'} onClick={()=>onSave(article.id)}><span className="article-heart" aria-hidden="true">{saved?'❤️':'🤍'}</span><span>{savingArticle===article.id?'Saving…':saved?'Liked':'Like'}</span></button></div></div></div></div>
 </motion.article>
}

function SettingsPanel({prefs,ceos,onSave,onClose}:{prefs:Preferences;ceos:CEO[];onSave:(p:Preferences)=>Promise<void>;onClose:()=>void}){
 const [draft,setDraft]=useState(prefs);const [saving,setSaving]=useState(false);const [error,setError]=useState('');
 async function save(){setSaving(true);setError('');try{await onSave(draft);onClose()}catch(e){setError((e as Error).message)}finally{setSaving(false)}}
 async function notifications(){if(!draft.notifications){if(!('Notification' in window)){setError('This browser does not support notifications.');return}const result=await Notification.requestPermission();if(result!=='granted'){setError('Notifications were not enabled in the browser.');return}}setDraft({...draft,notifications:!draft.notifications})}
 return <div className="modal-backdrop" onClick={onClose}><motion.section className="settings-panel" role="dialog" aria-modal="true" aria-labelledby="settings-title" initial={{opacity:0,x:35}} animate={{opacity:1,x:0}} onClick={e=>e.stopPropagation()}><div className="modal-heading"><div><h2 id="settings-title">Your newsroom.</h2></div><button className="icon-button" onClick={onClose} aria-label="Close settings"><X size={21}/></button></div><AccountSettings onClose={onClose}><p>A little less noise. A lot more of what you care about.</p><h4>Companies you follow</h4><div className="preference-chips">{ceos.map(c=><button key={c.id} className={draft.companies.includes(c.company)?'active':''} onClick={()=>setDraft({...draft,companies:draft.companies.includes(c.company)?draft.companies.filter(x=>x!==c.company):[...draft.companies,c.company]})}><CompanyLogo ceo={c}/>{c.company}</button>)}</div><h4>Your topics</h4><div className="preference-chips">{TOPICS.map(t=><button key={t} className={draft.topics.includes(t)?'active':''} onClick={()=>setDraft({...draft,topics:draft.topics.includes(t)?draft.topics.filter(x=>x!==t):[...draft.topics,t]})}>{t}</button>)}</div><label className="toggle-row"><span><strong>Personalized recommendations</strong><small>Use your chosen topics and saved stories to rank news.</small></span><input type="checkbox" checked={draft.personalization} onChange={e=>setDraft({...draft,personalization:e.target.checked})}/></label><div className="settings-grid"><label>Timezone<select value={draft.timezone} onChange={e=>setDraft({...draft,timezone:e.target.value})}>{['Europe/London','America/New_York','America/Los_Angeles','Asia/Kolkata','Asia/Tokyo','Australia/Sydney','UTC'].map(t=><option key={t}>{t}</option>)}</select></label><label>Morning briefing<input type="time" value={draft.briefing_time} onChange={e=>setDraft({...draft,briefing_time:e.target.value})}/></label><label>Evening recap<input type="time" value={draft.evening_time} onChange={e=>setDraft({...draft,evening_time:e.target.value})}/></label><label>Synthetic voice<select value={draft.voice} onChange={e=>setDraft({...draft,voice:e.target.value})}><option value="presenter">Each presenter’s voice</option>{ceos.map(c=><option key={c.id} value={c.voice}>{c.voice}</option>)}</select></label></div><label className="toggle-row"><span><strong>Auto-play narration</strong><small>Play generated audio after you choose Listen.</small></span><input type="checkbox" checked={draft.autoplay} onChange={e=>setDraft({...draft,autoplay:e.target.checked})}/></label><label className="toggle-row"><span><strong>Briefing notifications</strong><small>Notify when a new briefing arrives while the app is open.</small></span><input type="checkbox" checked={draft.notifications} onChange={()=>void notifications()}/></label><p className="settings-note"><ShieldCheck size={15}/> Your preferences stay with your account. Personalization is optional.</p>{error&&<div className="error-banner" role="alert">{error}</div>}<button className="primary-button" disabled={saving} onClick={()=>void save()}>{saving?'Saving…':'Save preferences'}<Check size={16}/></button></AccountSettings></motion.section></div>
}

const defaultPrefs:Preferences={companies:[],topics:[],saved:[],personalization:false,timezone:'Europe/London',briefing_time:'08:00',evening_time:'18:00',notifications:false,autoplay:false,voice:'presenter',speed:1};
export default function App(){
 const {user}=useAccount();
 const [ceos,setCeos]=useState<CEO[]>([]);const [news,setNews]=useState<Article[]>([]);const [prefs,setPrefs]=useState(defaultPrefs);const [health,setHealth]=useState<Health|null>(null);const [sources,setSources]=useState<Source[]>([]);const [briefing,setBriefing]=useState<Briefing|null>(null);const [briefHistory,setBriefHistory]=useState<Briefing[]>([]);
 const [feedReturn,setFeedReturn]=useState<FeedLocation>(readFeedLocation);
 const [screen,setScreen]=useState<Screen>(()=>new URLSearchParams(window.location.search).get('view')==='saved'?'saved':new URLSearchParams(window.location.search).get('view')==='videos'?'videos':new URLSearchParams(window.location.search).get('view')==='ask'?'ask':feedReturn.screen);const [company,setCompany]=useState(feedReturn.company);const [topic,setTopic]=useState(feedReturn.topic);const [period,setPeriod]=useState(feedReturn.period);const [query,setQuery]=useState(feedReturn.query);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [toast,setToast]=useState('');const [refreshing,setRefreshing]=useState(false);const [settings,setSettings]=useState(()=>new URLSearchParams(location.search).get('settings')==='pricing');const [mobileNav,setMobileNav]=useState(false);
 const [question,setQuestion]=useState('');const [messages,setMessages]=useState<(Message&{user?:boolean})[]>([]);const [asking,setAsking]=useState(false);const [sessionId,setSessionId]=useState(()=>new URLSearchParams(window.location.search).get('chat')||localStorage.getItem('newsroom-chat-session')||'');const [replyTo,setReplyTo]=useState<Article|null>(()=>{try{return JSON.parse(localStorage.getItem('newsroom-article-focus')||'null')}catch{return null}});const [audio,setAudio]=useState<AudioItem|null>(null);const [audioLoading,setAudioLoading]=useState(false);
 const [videoFocus,setVideoFocus]=useState<Video|null>(()=>{try{return JSON.parse(localStorage.getItem('newsroom-video-focus')||'null')}catch{return null}});
 useEffect(()=>{if(videoFocus)localStorage.setItem('newsroom-video-focus',JSON.stringify(videoFocus));else localStorage.removeItem('newsroom-video-focus')},[videoFocus]);
 const [video,setVideo]=useState<Video|null>(null);const [briefKind,setBriefKind]=useState('morning');const [more,setMore]=useState(feedReturn.more);
 const [chatCompany,setChatCompany]=useState('');const [chatSessions,setChatSessions]=useState<ChatSummary[]>([]);const [historyHasMore,setHistoryHasMore]=useState(false);const [historyOpen,setHistoryOpen]=useState(false);const [historyLoading,setHistoryLoading]=useState(false);const [historyError,setHistoryError]=useState('');const [chatLoading,setChatLoading]=useState(false);const [chatHasUpdate,setChatHasUpdate]=useState(false);const [queuedNews,setQueuedNews]=useState<Article[]|null>(null);
 const chatLoad=useRef(0);const historyRequest=useRef(0);const newsForeground=useRef(0);const screenRef=useRef(screen);screenRef.current=screen;const newsSnapshot=useRef<Article[]>([]);const feedStart=useRef<HTMLDivElement>(null);const restoreScroll=useRef<number|null>(null);const savedView=screen==='saved'||(screen==='ask'&&feedReturn.screen==='saved');
 const [pendingPresenters,setPendingPresenters]=useState<CEO[]>([]);
 const [savingArticle,setSavingArticle]=useState<string|null>(null);const likeInFlight=useRef(false);
 const [chatError,setChatError]=useState('');
 const [articleTopic,setArticleTopic]=useState(()=>localStorage.getItem('newsroom-article-topic')||'');const [includeRelated,setIncludeRelated]=useState(()=>localStorage.getItem('newsroom-article-related')!=='false');
 useEffect(()=>{localStorage.setItem('newsroom-article-topic',articleTopic);localStorage.setItem('newsroom-article-related',String(includeRelated))},[articleTopic,includeRelated]);
 useEffect(()=>{if(replyTo)localStorage.setItem('newsroom-article-focus',JSON.stringify(replyTo));else localStorage.removeItem('newsroom-article-focus')},[replyTo]);
 const inputRef=useRef<HTMLInputElement>(null);const chatEnd=useRef<HTMLDivElement>(null);const notificationRef=useRef('');const newsRequest=useRef(0);const briefRequest=useRef(0);
 const fetchNews=useCallback(async(background=false)=>{if(background&&newsForeground.current)return;const version=++newsRequest.current;if(!background)newsForeground.current=version;try{const params=new URLSearchParams({company,topic,q:query,period,saved:String(savedView)});const d=await request<{articles:Article[]}>('/news?'+params);if(version!==newsRequest.current)return;if(background&&newsSnapshot.current.length){if(JSON.stringify(d.articles)!==JSON.stringify(newsSnapshot.current))setQueuedNews(d.articles)}else{newsSnapshot.current=d.articles;setNews(d.articles);setQueuedNews(null)}setError('')}catch(e){if(version===newsRequest.current&&!background)setError((e as Error).message)}finally{if(newsForeground.current===version)newsForeground.current=0;if(version===newsRequest.current&&!background)setLoading(false)}},[company,topic,query,period,savedView]);
 const fetchBrief=useCallback(async()=>{const version=++briefRequest.current;const b=await request<Briefing>('/briefings/today?kind='+briefKind+(screen==='briefing'&&company?'&company='+encodeURIComponent(company):''));if(version===briefRequest.current)setBriefing(b)},[briefKind,company,screen]);
 useEffect(()=>{Promise.all([request<CEO[]>('/ceos'),request<Preferences>('/preferences'),request<Health>('/health'),request<Source[]>('/sources')]).then(([c,p,h,s])=>{setCeos(c);setPrefs(p);setHealth(h);setSources(s)}).catch(e=>{setError(e.message);setLoading(false)})},[]);
 useEffect(()=>{setLoading(true);const t=setTimeout(()=>void fetchNews(),180);setMore(8);return ()=>{clearTimeout(t);++newsRequest.current}},[fetchNews]);
 useEffect(()=>{void fetchBrief().catch(e=>setError(e.message))},[fetchBrief]);
 useEffect(()=>{if(screen==='briefing')request<Briefing[]>('/briefings/history').then(setBriefHistory).catch(e=>setError(e.message))},[screen,briefKind]);
 useEffect(()=>{void refreshChatHistory();if(sessionId)void openSession(sessionId,false)},[]);
 useEffect(()=>{localStorage.setItem('newsroom-feed-location',JSON.stringify(feedReturn))},[feedReturn]);
 useEffect(()=>{if(screen!=='ask'&&restoreScroll.current!==null&&!loading){const top=restoreScroll.current;restoreScroll.current=null;requestAnimationFrame(()=>window.scrollTo({top,behavior:'instant'}))}},[screen,loading,news]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return ()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(screen!=='ask'||historyOpen)return;const lastUser=messages.map(m=>!!m.user).lastIndexOf(true);const answer=document.querySelector(`[data-message-index="${lastUser+1}"]`);if(!asking&&answer)answer.scrollIntoView({behavior:'smooth',block:'start'});else chatEnd.current?.scrollIntoView({behavior:'smooth',block:'nearest'})},[messages,asking,screen,historyOpen]);
 useEffect(()=>{const timer=setInterval(()=>{void request<Health>('/health').then(h=>{setHealth(h);void fetchNews(true)});void fetchBrief().then(()=>{}).catch(()=>{})},60000);return ()=>clearInterval(timer)},[health?.article_count,fetchNews,fetchBrief]);
 useEffect(()=>{
  if(!briefing)return;
  const clock=new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:prefs.timezone});
  const scheduledTime=briefing.kind==='evening'?prefs.evening_time:prefs.briefing_time;
  const ready=clock>=scheduledTime&&briefing.articles.length>0;
  const signature=briefing.date+briefing.kind+(ready?'-ready':'-pending');
  if(ready&&prefs.notifications&&'Notification' in window&&Notification.permission==='granted'&&notificationRef.current&&notificationRef.current!==signature)new Notification('Your CEO Newsroom briefing is ready',{body:`${briefing.articles.length} stories, with original sources.`});
  notificationRef.current=signature;
 },[briefing,prefs.notifications,prefs.timezone,prefs.briefing_time,prefs.evening_time]);
 async function savePrefs(p:Preferences){const saved=await request<Preferences>('/preferences',p,'PUT');setPrefs(saved);setToast('Preferences saved');await fetchNews()}
 async function saveStory(id:string){if(likeInFlight.current)return;likeInFlight.current=true;setSavingArticle(id);setError('');const liked=prefs.saved.includes(id);try{const next=await request<Preferences>('/preferences',{...prefs,saved:liked?prefs.saved.filter(x=>x!==id):[...prefs.saved,id]},'PUT');setPrefs(next);setToast(liked?'Article removed from Saved articles':'❤️ Article liked and saved');await fetchNews()}catch(e){setError((e as Error).message)}finally{likeInFlight.current=false;setSavingArticle(null)}}
 async function refresh(){setRefreshing(true);setError('');try{const r=await request<{added:number;sources_available:number;sources_total:number;ai_error:string|null}>('/news/refresh',{});await Promise.all([fetchNews(),fetchBrief(),request<Source[]>('/sources').then(setSources),request<Health>('/health').then(setHealth)]);setToast(`${r.added} new stories · ${r.sources_available}/${r.sources_total} sources available${r.ai_error?' · AI enrichment unavailable':''}`)}catch(e){setError((e as Error).message)}finally{setRefreshing(false)}}
 async function ask(e?:FormEvent,provided?:string,followUp?:Message){
  e?.preventDefault();const text=(provided||question).trim();if(!text||asking||chatLoading)return;if(screen!=='ask')enterChat();
  const submittedQuestion=text;
  const previous:string[]=[];for(const m of [...messages].reverse()){if(m.user){if(previous.length)break;continue}previous.push(m.presenter)}
  const responding=followUp?questionPresenters(text,ceos,ceos.find(c=>c.id===followUp.presenter)?.company||'',previous):videoFocus?videoPresenters(text,ceos,videoFocus,articleTopic,previous):replyTo?articlePresenters(text,ceos,replyTo,articleTopic,previous):questionPresenters(submittedQuestion,ceos,chatCompany,previous);
  if(!responding.length&&messages.some(m=>!m.user&&m.follow_up_question))responding.push(...ceos.filter(c=>previous.includes(c.id)));
  setHistoryOpen(false);setPendingPresenters(responding);setQuestion('');setAsking(true);setError('');setChatError('');
  setMessages(m=>m.at(-1)?.user&&m.at(-1)?.text===text?m:[...m,{presenter:'user',text,user:true,citations:[]}]);
  try{
   const r=await request<{messages:Message[];session_id:string}>('/chat',{question:submittedQuestion,session_id:sessionId||null,presenter:responding.length===1?responding[0].id:null,period,article_id:replyTo?.id||null,video_id:videoFocus?.id||null,topic:(replyTo||videoFocus)?articleTopic.trim()||null:null,include_related:includeRelated,follow_up:!!followUp});
   setSessionId(r.session_id);localStorage.setItem('newsroom-chat-session',r.session_id);setMessages(m=>[...m,...r.messages]);setChatHasUpdate(screenRef.current!=='ask');if(screenRef.current==='ask')chatUrl(r.session_id);void refreshChatHistory();
  }catch(e){setChatError((e as Error).message);setQuestion(text);setReplyTo(replyTo)}finally{setAsking(false);setPendingPresenters([])}
 }
 async function listen(text:string,presenter:string,title:string){if(audioLoading)return;setAudioLoading(true);try{const tracks:AudioTrack[]=[];for(const chunk of narrationChunks(text)){const r=await request<{url:string;voice:string}>('/audio',{text:chunk,presenter,voice:prefs.voice});tracks.push({...r,title})}if(!tracks.length)return;setAudio({...tracks[0],title,tracks});if(prefs.autoplay)setTimeout(()=>{document.querySelector<HTMLAudioElement>('.audio-player audio')?.play().catch(()=>{})},100)}catch(e){setError((e as Error).message)}finally{setAudioLoading(false)}}
 async function listenBriefing(){if(audioLoading||!briefing?.articles.length)return;setAudioLoading(true);try{const tracks:AudioTrack[]=[];for(const a of briefing.articles){const r=await request<{url:string;voice:string}>('/audio',{text:(a.title+'. '+a.summary).slice(0,3500),presenter:a.presenters[0]||'sam_altman',voice:prefs.voice});tracks.push({...r,title:a.title})}setAudio({...tracks[0],tracks});if(prefs.autoplay)setTimeout(()=>{document.querySelector<HTMLAudioElement>('.audio-player audio')?.play().catch(()=>{})},100)}catch(e){setError((e as Error).message)}finally{setAudioLoading(false)}}
 function chatUrl(id=sessionId){const url=new URL(window.location.href);url.searchParams.set('view','ask');if(id)url.searchParams.set('chat',id);else url.searchParams.delete('chat');window.history.replaceState(null,'',url)}
 function enterChat(showHistory=false){if(screen!=='ask'){setFeedReturn({screen,company,topic,period,query,more,scroll:window.scrollY})}setScreen('ask');setMobileNav(false);setChatHasUpdate(false);setHistoryOpen(showHistory);chatUrl();if(showHistory)void refreshChatHistory()}
 async function refreshChatHistory(older=false){const version=++historyRequest.current;setHistoryLoading(true);setHistoryError('');try{const r=await request<{sessions:ChatSummary[]}>('/chat/sessions?limit=100&offset='+(older?chatSessions.length:0));if(version===historyRequest.current){setChatSessions(previous=>older?[...previous,...r.sessions.filter(s=>!previous.some(p=>p.id===s.id))]:r.sessions);setHistoryHasMore(r.sessions.length===100)}}catch(e){if(version===historyRequest.current)setHistoryError((e as Error).message)}finally{if(version===historyRequest.current)setHistoryLoading(false)}}
 async function openSession(id:string,show=true){if(asking)return;if(show)enterChat();const version=++chatLoad.current;setChatLoading(true);setChatError('');try{const r=await request<SavedChat>('/chat/sessions/'+encodeURIComponent(id));if(version!==chatLoad.current)return;setMessages(r.messages.map(m=>({...m,user:m.role==='user'})));setSessionId(id);localStorage.setItem('newsroom-chat-session',id);setReplyTo(r.article_context);setVideoFocus(r.video_context);setArticleTopic(r.topic);setIncludeRelated(r.include_related);setChatCompany(r.video_context?.company||r.article_context?.companies[0]||ceos.find(c=>c.id===r.messages.at(-1)?.presenter)?.company||'');setQuestion('');setHistoryOpen(false);setChatHasUpdate(false);if(screenRef.current==='ask'||show)chatUrl(id);if(r.missing_article)setChatError('This saved article is no longer available, but the conversation is still saved.')}catch(e){if(version===chatLoad.current){setHistoryError((e as Error).message);setHistoryOpen(true)}}finally{if(version===chatLoad.current)setChatLoading(false)}}
 function resetChat(article:Article|null=null,clip:Video|null=null){if(asking)return;++chatLoad.current;setChatLoading(false);setMessages([]);setSessionId('');localStorage.removeItem('newsroom-chat-session');setReplyTo(article);setVideoFocus(clip);setArticleTopic('');setIncludeRelated(true);setChatCompany(clip?.company||article?.companies[0]||'');setQuestion(article?'Explain this topic, how it works, and the impact for each company.':clip?'Explain what is shown and said, how it works, and the impact for each company.':'');setChatError('');setHistoryOpen(false);chatUrl('')}
 function backToArticles(){const location=feedReturn;setScreen(location.screen);setCompany(location.company);setTopic(location.topic);setPeriod(location.period);setQuery(location.query);setMore(location.more);setMobileNav(false);restoreScroll.current=location.scroll;const url=new URL(window.location.href);url.searchParams.delete('chat');if(location.screen==='saved'||location.screen==='videos')url.searchParams.set('view',location.screen);else url.searchParams.delete('view');window.history.replaceState(null,'',url)}
 function navigate(s:Screen,c=''){if(s==='ask'){enterChat(true);return}const url=new URL(window.location.href);url.searchParams.delete('chat');if(s==='videos'||s==='saved')url.searchParams.set('view',s);else url.searchParams.delete('view');window.history.replaceState(null,'',url);if(s==='saved')setPeriod('all');setScreen(s);setCompany(c);setMobileNav(false);setQuery('');setTopic('');setMore(8)}
 function reply(a:Article){if(asking){enterChat();setToast('Your current answer is still being prepared.');return}const existing=chatSessions.find(c=>c.article_id===a.id);if(replyTo?.id===a.id&&sessionId){enterChat();return}if(existing){void openSession(existing.id);return}enterChat();resetChat(a);setTimeout(()=>window.scrollTo({top:0,behavior:'smooth'}),0)}
 function clearArticle(){setReplyTo(null);setVideoFocus(null);setArticleTopic('')}
 function askVideo(v:Video){setVideo(null);if(asking){enterChat();setToast('Your current answer is still being prepared.');return}const existing=chatSessions.find(c=>c.video_id===v.id);if(videoFocus?.id===v.id&&sessionId){enterChat();return}if(existing){void openSession(existing.id);return}enterChat();resetChat(null,v);setTimeout(()=>window.scrollTo({top:0,behavior:'smooth'}),0)}
 function showNewArticles(){if(!queuedNews)return;newsSnapshot.current=queuedNews;setNews(queuedNews);setQueuedNews(null);setTimeout(()=>feedStart.current?.scrollIntoView({behavior:'smooth',block:'start'}),0)}
 const newArticleCount=queuedNews?.filter(a=>!newsSnapshot.current.some(old=>old.id===a.id)).length||0;
 const selectedCompany=screen==='ask'?chatCompany:company;
 const latestUserIndex=messages.map(m=>!!m.user).lastIndexOf(true);
 const activeCEO=ceos.find(c=>c.company===selectedCompany);const available=sources.filter(s=>s.status==='available').length;const total=sources.length;
 const orderedNews=screen==='chat'&&!company&&!query?[...news.filter(a=>a.companies.length),...news.filter(a=>!a.companies.length)]:news;
 const pageTitle=screen==='chat'?'In good company.':screen==='companies'?(company?`${company}, in focus.`:'Follow the companies.'):screen==='briefing'?'Your daily download.':screen==='videos'?'A front-row seat.':screen==='ask'?'Your conversations.':screen==='saved'?'Saved articles.':'Follow the facts.';
 const subtitle=screen==='saved'?'Articles you’ve liked, kept here for later. Tap the heart again to remove one.':screen==='chat'?'The biggest stories in tech. The people behind them. One conversation.':screen==='ask'?'Saved chats, useful follow-ups, and an easy way back to your articles.':screen==='briefing'?'The stories that matter, distilled into a conversation.':screen==='videos'?'Official company uploads, updated every day. No fan channels or reposts.':screen==='sources'?'Original reporting. Clear attribution. No invented headlines.':'The latest reporting, with the context you came for.';
 return <div className="app-shell"><aside className={`sidebar ${mobileNav?'mobile-open':''}`}><a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('chat')}}><span className="brand-icon"><MessageCircle size={22}/><span/></span><span>CEO<span className="brand-second">NEWSROOM</span></span><span className="version">3.0</span></a><div className="sidebar-inner"><p className="sidebar-caption">YOUR DAILY TECH SIGNAL</p><nav aria-label="Primary navigation">{NAV.map(n=><button key={n.id} className={`nav-item ${screen===n.id?'active':''}`} onClick={()=>navigate(n.id)}><n.icon size={18}/>{n.label}{n.id==='chat'&&<span className="nav-live"/>}{n.id==='briefing'&&briefing&&briefing.articles.length>0&&<span className="nav-count">{briefing.articles.length}</span>}</button>)}</nav><div className="sidebar-divider"/><div className="section-caption"><span>IN THE ROOM</span><span>08</span></div><nav aria-label="Company navigation">{ceos.map(c=><button className={`company-nav ${company===c.company?'selected':''}`} key={c.id} onClick={()=>navigate('companies',c.company)}><CompanyLogo ceo={c}/>{c.company}<span style={{background:c.color}}/></button>)}</nav><div className="sidebar-divider"/><button className={`nav-item ${screen==='saved'?'active':''}`} onClick={()=>navigate('saved')}><Bookmark size={17}/>Saved articles{prefs.saved.length>0&&<span className="nav-count">{prefs.saved.length}</span>}</button><button className={`nav-item ${screen==='sources'?'active':''}`} onClick={()=>navigate('sources')}><ShieldCheck size={17}/>Our sources<ArrowUpRight size={14}/></button></div><div className="sidebar-footer"><div className="simulation-note"><ShieldCheck size={16}/><div><strong>Real news. AI presenters.</strong><p>Independent simulations.<br/>No executive endorsement.</p></div></div><button className="profile-button" onClick={()=>setSettings(true)}><span className="user-avatar">U</span><span>{user.name}<small>{user.email}</small></span><Settings size={16}/></button></div></aside>
 <div className="workspace"><header className="topbar"><button className="icon-button mobile-menu" aria-label="Toggle navigation" onClick={()=>setMobileNav(!mobileNav)}><Menu size={20}/></button><div className="breadcrumbs">Workspace<span>/</span><strong>{screenLabels[screen]}</strong></div><div className="topbar-actions"><span className="connection-status"><span/>{health?.article_count?`${health.article_count} sourced stories`:'Connecting to sources'}</span><span className="topbar-divider"/><button className="icon-button" aria-label="Open settings" onClick={()=>setSettings(true)}><SlidersHorizontal size={18}/></button><span className="user-avatar small">U</span></div></header>
 <main><div className="page-heading"><div><div className="eyebrow"><span/> THE AI TECH GROUP CHAT</div><h1>{pageTitle}</h1><p>{subtitle}</p></div><div className="heading-right"><span className="today-date">{new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'long',timeZone:prefs.timezone})}</span><button className="secondary-button" disabled={refreshing} onClick={()=>void refresh()}><RefreshCw size={14} className={refreshing?'spinning':''}/>{refreshing?'Refreshing…':'Refresh news'}</button></div></div>
 {(screen==='chat'||screen==='companies'||screen==='ask')&&<section className="ceo-selector" aria-label="Choose an AI presenter">{ceos.map((c,i)=><motion.button key={c.id} className={`ceo-tile ${selectedCompany===c.company?'selected':''}`} onClick={()=>{if(screen==='ask'){setChatCompany(chatCompany===c.company?'':c.company);if(replyTo&&!replyTo.companies.includes(c.company))clearArticle()}else setCompany(company===c.company?'':c.company)}} style={{'--company':c.color} as CSSProperties} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*.04}} aria-pressed={selectedCompany===c.company}><div className="portrait-stage"><span className="tile-index">0{i+1}</span><span className="tile-ai">AI</span><img src={c.avatar+'?v=3.0.3'} alt={c.name} className="ceo-portrait"/><span className="portrait-line"/></div><div className="tile-caption"><strong>{c.name.split(' ')[0]} {c.name==='Tim Cook'?'Cook':''}</strong><span>{c.company}<span className="company-dot"/></span></div></motion.button>)}</section>}
 {error&&<div className="error-banner" role="alert"><AlertCircle size={17}/><span>{error}</span><button className="icon-button" onClick={()=>setError('')} aria-label="Dismiss error"><X size={15}/></button></div>}
 <div className="content-grid"><section className="main-feed">
 {screen==='sources'?<div className="sources-directory"><div className="feed-title"><h2>Source directory</h2><span>{available} / {total} available</span></div>{sources.map(s=><div className="source-row" key={s.id}><span className={`source-status ${s.status==='available'?'ok':''}`}/><div><a href={s.url} target="_blank" rel="noopener noreferrer">{s.name}<ArrowUpRight size={14}/></a><p>{s.kind==='rss'?'RSS / Atom feed':'Public announcement metadata'} · {s.detail}</p><small>Checked {s.checked_at?dateText(s.checked_at,prefs.timezone)+' at '+timeText(s.checked_at,prefs.timezone):'pending'}</small></div><span className="status-label">{s.status}</span></div>)}<p className="fineprint">Availability is checked during ingestion. NVIDIA RSS is intended for personal, non-commercial use. Full articles stay with their publishers.</p></div>
 :screen==='videos'?<YouTubeSection ceos={ceos} company={company||'all'} onCompany={setCompany} timezone={prefs.timezone} onPlay={setVideo} onAsk={askVideo} savedVideoIds={chatSessions.flatMap(s=>s.video_id?[s.video_id]:[])}/>
 :screen==='briefing'?<><div className="briefing-heading"><div className="segmented">{['morning','evening','weekly'].map(k=><button key={k} className={briefKind===k?'active':''} onClick={()=>setBriefKind(k)}>{k==='morning'?'Morning briefing':k==='evening'?'Evening recap':'Weekly summary'}</button>)}</div><select aria-label="Briefing company" value={company} onChange={e=>setCompany(e.target.value)}><option value="">All companies</option>{ceos.map(c=><option key={c.id}>{c.company}</option>)}</select><button className="icon-button" aria-label="Listen to briefing" disabled={!briefing?.articles.length} onClick={()=>void listenBriefing()}><Headphones size={19}/></button></div><div className="briefing-banner"><Sun size={29}/><div><span className="eyebrow">{briefing?.date} · {prefs.timezone}</span><h2>{briefing?.articles.length||0} stories. A clearer picture.</h2><p>{briefing?.empty?'No dated reporting for this period yet. Refresh sources or check the weekly summary.':'Source-backed updates, presented by the people in your room.'}</p></div></div>{briefing?.articles.map((a,i)=><NewsCard key={a.id} article={a} index={i} ceos={ceos} prefs={prefs} savingArticle={savingArticle} onSave={id=>void saveStory(id)} onAudio={(...args)=>void listen(...args)} onReply={reply}/>)}{briefing?.videos&&briefing.videos.length>0&&<div className="related-videos"><h3>From the official channels</h3><div className="video-grid">{briefing.videos.map(v=><button className="video-card" key={v.id} onClick={()=>setVideo(v)}><img src={v.thumbnail} alt=""/><h3>{v.title}</h3><p>{v.channel} · {dateText(v.published_at,prefs.timezone)}</p></button>)}</div></div>}{briefHistory.length>0&&<details className="briefing-history"><summary><Clock size={15}/>Previous briefings</summary>{briefHistory.map(b=><button key={b.id} onClick={()=>setBriefing(b)}>{dateText(b.date,prefs.timezone)} · {b.kind}<span>{b.articles.length} stories</span></button>)}</details>}</>
 :<>{screen!=='ask'&&<><div ref={feedStart} className="feed-toolbar"><div className="feed-tabs"><button className={!company?'active':''} onClick={()=>setCompany('')}>{screen==='saved'?`Liked articles (${prefs.saved.length})`:'All updates'}</button>{activeCEO?<button className="active company-feed-tab" onClick={()=>setCompany('')}>{activeCEO.company}<X size={12}/></button>:<button onClick={()=>setPeriod(period==='today'?'all':'today')} className={period==='today'?'active':''}>Today<span className="live-dot"/></button>}</div><div className="toolbar-tools"><label className="search-box"><Search size={14}/><input aria-label="Search news" placeholder="Search the newsroom" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="Clear search" onClick={()=>setQuery('')}><X size={13}/></button>}</label><select aria-label="Date filter" value={period} onChange={e=>setPeriod(e.target.value)}><option value="all">Latest</option><option value="today">Today</option><option value="week">This week</option><option value="month">This month</option></select></div></div><div className="topic-filters"><button className={!topic?'active':''} onClick={()=>setTopic('')}>All topics</button>{TOPICS.slice(0,5).map(t=><button key={t} className={topic===t?'active':''} onClick={()=>setTopic(topic===t?'':t)}>{t}</button>)}<select aria-label="All topic filters" value={topic} onChange={e=>setTopic(e.target.value)}><option value="">More</option>{TOPICS.map(t=><option key={t}>{t}</option>)}</select></div>
 </>}
 {screen!=='ask'&&queuedNews&&<div className="feed-update-banner" role="status"><span>{newArticleCount?`${newArticleCount} new ${newArticleCount===1?'article':'articles'} ready`:'Article updates are ready'}</span><button onClick={showNewArticles}>Show updates<ArrowUp size={14}/></button></div>}
 {screen==='ask'&&<><div className="chat-workspace-toolbar"><button className="secondary-button" onClick={backToArticles}><ChevronLeft size={15}/>{feedReturn.screen==='videos'?'Back to videos':'Back to articles'}{newArticleCount>0&&<span className="chat-new-count">{newArticleCount} new</span>}</button><div><button className="secondary-button" onClick={()=>{setHistoryOpen(!historyOpen);if(!historyOpen)void refreshChatHistory()}} aria-expanded={historyOpen}><Clock size={14}/>Chat history{chatSessions.length>0&&<span>{chatSessions.length}</span>}</button><button className="secondary-button" disabled={asking||chatLoading} onClick={()=>resetChat()}><Plus size={14}/>New chat</button></div><small>{chatLoading?'Opening conversation…':asking?'Preparing your answer…':sessionId?'Saved automatically':'Saves after the first answer'}</small></div>{historyOpen&&<ChatHistory sessions={chatSessions} current={sessionId} loading={historyLoading} error={historyError} disabled={asking} hasMore={historyHasMore} ceos={ceos} onOpen={id=>void openSession(id)} onRefresh={()=>void refreshChatHistory()} onMore={()=>void refreshChatHistory(true)}/>}</>}
 <div className="day-divider"><span/>{screen==='saved'?'YOUR SAVED ARTICLES':screen==='ask'?'THE CONVERSATION STARTS HERE':period==='today'?'TODAY’S REPORTING':'LATEST FROM THE ROOM'}<span/></div>
 {screen==='ask'&&videoFocus&&<VideoFocus video={videoFocus} ceos={ceos} topic={articleTopic} onTopic={setArticleTopic} related={includeRelated} onRelated={setIncludeRelated} onClear={clearArticle} onAsk={q=>void ask(undefined,q)} disabled={asking||chatLoading}/>}
 {screen==='ask'&&replyTo&&<ArticleFocus article={replyTo} ceos={ceos} timezone={prefs.timezone} topic={articleTopic} onTopic={setArticleTopic} related={includeRelated} onRelated={setIncludeRelated} onClear={clearArticle} onAsk={q=>void ask(undefined,q)} disabled={asking||chatLoading}/>}
 {screen==='ask'&&!replyTo&&!videoFocus&&messages.length===0?<div className="ask-welcome"><div className="ask-symbol"><MessageCircle size={28}/><Sparkles size={14}/></div><h2>Good questions start<br/>great conversations.</h2><p>Choose a presenter above, or ask the whole room.<br/>Every answer comes back to the sources.</p><div className="suggestion-grid">{['What happened at NVIDIA today?','Compare OpenAI and Anthropic’s latest news.','What is Apple doing in AI?','Summarize Google’s latest research.'].map(s=><button key={s} onClick={()=>void ask(undefined,s)}>{s}<ArrowUpRight size={16}/></button>)}</div></div>:screen!=='ask'&&(loading?<div className="loading-state"><RefreshCw className="spinning" size={20}/>Opening the newsroom…</div>:news.length===0?<div className="empty-state"><Search size={30}/><h3>{screen==='saved'?(prefs.saved.length?'No liked articles match these filters.':'Your favorite reads, all in one place.'):'No stories for these filters.'}</h3><p>{screen==='saved'?(prefs.saved.length?'Try another search, topic, or date range.':'Tap 🤍 on any article to like it and save it here for later.'):'Try another company, a broader date range, or refresh the sources.'}</p><button className="secondary-button" onClick={()=>{if(screen==='saved'&&!prefs.saved.length)navigate('chat');else{setCompany('');setTopic('');setPeriod('all');setQuery('')}}}>{screen==='saved'&&!prefs.saved.length?'Explore articles':'Reset filters'}<ArrowRight size={14}/></button></div>:orderedNews.slice(0,more).map((a,i)=><NewsCard key={a.id} article={a} index={i} ceos={ceos} prefs={prefs} savingArticle={savingArticle} onSave={id=>void saveStory(id)} onAudio={(...args)=>void listen(...args)} onReply={reply}/>))}
 {screen!=='ask'&&news.length>more&&<button className="load-more" onClick={()=>setMore(m=>m+8)}>More from the room<ChevronDown size={16}/><span>{news.length-more} stories</span></button>}
 {screen==='ask'&&<>{messages.length>0&&<div className="conversation-messages">{screen!=='ask'&&<div className="day-divider"><span/>YOUR CONVERSATION<span/></div>}{messages.map((m,i)=>m.user?<div className="user-message" key={i}><p>{m.text}</p><span className="user-avatar small">U</span></div>:<div className="answer-message" key={i} data-message-index={i} data-presenter={m.presenter} lang={m.language||'en'} dir={m.language==='ar'?'rtl':undefined} style={{"--company":ceos.find(c=>c.id===m.presenter)?.color||"#c6e9a8"} as CSSProperties}><CEOAvatar ceo={ceos.find(c=>c.id===m.presenter)}/><div><div className="message-byline"><strong>{ceos.find(c=>c.id===m.presenter)?.name||'The Newsroom'}</strong>{ceos.find(c=>c.id===m.presenter)&&<span className="presenter-company">{ceos.find(c=>c.id===m.presenter)!.company}</span>}<span className="ai-label">AI presenter</span><button className="icon-button" aria-label="Listen to answer" onClick={()=>void listen(answerNarration(m),m.presenter==='newsroom'?'sam_altman':m.presenter,'Newsroom answer')}><Volume2 size={14}/></button></div><p>{m.text}</p>{m.answer_kind&&m.answer_kind!=='source_based'&&<div className="answer-assessment"><span>{m.answer_kind==='prediction'?'Prediction · uncertain':m.answer_kind==='analysis'?'Reasoned assessment':'General explanation'}</span>{m.assessment_note&&<small>{m.assessment_note}</small>}</div>}{m.explanation?<ExplanationAnswer message={m} citation={a=><SourceCitation key={a.id} article={a} timezone={prefs.timezone}/>}/>:<div className="answer-citations">{m.citations?.map(a=><SourceCitation key={a.id} article={a} timezone={prefs.timezone}/>)}</div>}<FollowUpPrompts message={m} ceo={ceos.find(c=>c.id===m.presenter)} active={i>latestUserIndex&&(m.article_id||null)===(replyTo?.id||null)&&(m.video_id||null)===(videoFocus?.id||null)} disabled={asking} onAsk={(q,message)=>void ask(undefined,q,message)}/></div></div>)}</div>}{asking&&<ThinkingIndicator presenters={pendingPresenters} video={!!videoFocus}/>}{chatError&&<div className="chat-error" role="alert"><AlertCircle size={16}/><span>{chatError}</span></div>}<div ref={chatEnd} className="chat-end-anchor"/>
 <div className="composer-wrap">{videoFocus&&<div className="reply-context"><VideoIcon size={13}/><span>Video: {videoFocus.title}</span><button className="icon-button" aria-label="Cancel video question" onClick={clearArticle} disabled={asking}><X size={14}/></button></div>}{replyTo&&<div className="reply-context"><MessageCircle size={13}/><span>About: {replyTo.title}</span><button className="icon-button" aria-label="Cancel article reply" onClick={clearArticle} disabled={asking}><X size={14}/></button></div>}<form className="chat-composer" onSubmit={e=>void ask(e)}><span className="composer-icon"><Sparkles size={18}/></span><input ref={inputRef} aria-label="Ask the newsroom" value={question} onChange={e=>setQuestion(e.target.value)} placeholder={videoFocus?'Ask about the speech, visuals, or a timestamp…':replyTo?'Ask about this article…':activeCEO?`Ask ${activeCEO.name.split(' ')[0]} about ${activeCEO.company}…`:'Ask the room a question…'} maxLength={2000}/><button className="send-button" aria-label="Send question" disabled={asking||chatLoading||!question.trim()}><ArrowUp size={20}/></button></form><div className="composer-footnote"><span><ShieldCheck size={11}/> AI simulations · Sources and labeled assessments</span><span>Enter to send</span></div>{messages.length>0&&<button className="new-conversation" disabled={asking} onClick={()=>resetChat()}><Plus size={12}/>New conversation</button>}</div></>}</>}
 </section><aside className="right-rail"><div className="rail-heading"><span>THE DAILY DOWNLOAD</span><Sun size={15}/></div><section className="briefing-widget"><span className="edition">{briefKind==='weekly'?'WEEKLY':'TODAY’S'} EDITION <span>01</span></span><h2>Ahead of<br/>the conversation.</h2><p>Your tech world, in a few<br/>well-informed minutes.</p><div className="briefing-meta"><span><MessageCircle size={13}/>{briefing?.articles.length||0} top stories</span><span><Clock size={13}/>{Math.max(1,Math.ceil((briefing?.articles.length||0)*.4))} min read</span></div><button className="briefing-cta" onClick={()=>navigate('briefing')}>Open your briefing<ArrowRight size={17}/></button><button className="listen-briefing" disabled={audioLoading||!briefing?.articles.length} onClick={()=>void listenBriefing()}><Headphones size={15}/>{audioLoading?'Preparing narration…':'Or, sit back and listen'}</button></section>
 <div className="rail-heading headlines-heading"><span>ON THE RADAR</span><span className="live-tag">SOURCED</span></div><div className="radar-list">{(briefing?.articles.length?briefing.articles:news).slice(0,4).map((a,i)=><a key={a.id} href={a.url} target="_blank" rel="noopener noreferrer"><span className="radar-number">0{i+1}</span><div><h3>{a.title}</h3><span>{a.companies[0]||a.source} · {dateText(a.published_at,prefs.timezone)}</span></div><ArrowUpRight size={14}/></a>)}</div>
 <div className="rail-heading"><span>EXPLORE A TOPIC</span><ArrowUpRight size={14}/></div><div className="rail-topics">{['AI research','Robotics','Product launches'].map(t=><button key={t} onClick={()=>{setScreen('chat');setTopic(t);setCompany('')}}><span>#</span>{t}<ArrowRight size={13}/></button>)}</div><div className="source-health"><span className="healthy-dot"/><span>{available} of {total||14} sources available<small>Sources checked automatically</small></span><button className="icon-button" aria-label="View source status" onClick={()=>navigate('sources')}><ArrowUpRight size={16}/></button></div><p className="rail-disclosure">An independent newsroom powered by AI.<br/>The news is real. The group chat is simulated.</p></aside></div>
 </main><footer className="workspace-footer"><span>Stay curious. Stay in good company.</span><span>CEO NEWSROOM <span className="footer-dot"/> 2026</span></footer></div>
 {screen!=='ask'&&(messages.length>0||replyTo||videoFocus)&&<button className="resume-chat-button" style={audio?{bottom:105}:undefined} onClick={()=>enterChat()}><MessageCircle size={17}/>{asking?'Answer in progress…':chatHasUpdate?'Answer ready · Open chat':'Open chat'}{chatHasUpdate&&<span/>}</button>}
 <AnimatePresence>{settings&&<SettingsPanel prefs={prefs} ceos={ceos} onSave={savePrefs} onClose={()=>setSettings(false)}/>}</AnimatePresence>{toast&&<div className="toast" role="status"><Check size={16}/>{toast}</div>}{audio&&<AudioPlayer key={audio.url} item={audio} speed={prefs.speed} onClose={()=>setAudio(null)}/>} {audioLoading&&<div className="audio-loading" role="status"><Headphones size={16}/>Preparing synthetic narration…</div>}
 {video&&<div className="modal-backdrop" onClick={()=>setVideo(null)}><section className="video-modal" role="dialog" aria-modal="true" aria-label={video.title} onClick={e=>e.stopPropagation()}><div className="modal-heading"><h3>{video.title}</h3><button className="icon-button" aria-label="Close video" onClick={()=>setVideo(null)}><X size={21}/></button></div>{video.embeddable!==false?<iframe title={video.title} src={`https://www.youtube-nocookie.com/embed/${video.id}`} referrerPolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen/>:<div className="video-unembeddable"><VideoIcon size={30}/><p>This official upload requires playback on YouTube. Use the link below to watch it.</p></div>}<VideoChatButton className="video-modal-chat" video={video} ceos={ceos} resume={chatSessions.some(s=>s.video_id===video.id)} onClick={()=>askVideo(video)}/><a href={video.url} target="_blank" rel="noopener noreferrer">Watch on YouTube<ExternalLink size={14}/></a></section></div>}
 </div>
}
